  function updateSceneryOcclusion(){if(occlusionTick++%3!==0)return;const model=playerModels[activePlayer];if(!model)return;const targets=[model.position.clone().add(new THREE.Vector3(0,1.05,0))];if(branchState)branchState.options.forEach(id=>targets.push(worldPoint(id).add(new THREE.Vector3(0,.55,0))));const faded=new Set();targets.forEach(target=>{occlusionDirection.copy(target).sub(camera.position);const distance=occlusionDirection.length();if(distance<.1)return;occlusionRaycaster.set(camera.position,occlusionDirection.normalize());occlusionRaycaster.near=0;occlusionRaycaster.far=distance-.25;occlusionRaycaster.intersectObjects(sceneryMeshes,false).forEach(hit=>{const group=hit.object.userData.sceneryGroup;if(group)faded.add(group)})});sceneryGroups.forEach(group=>{const close=group.position.distanceTo(camera.position)<2.5,target=faded.has(group)||close?.1:1;group.userData.occlusionOpacity+=(target-group.userData.occlusionOpacity)*.38;group.traverse(object=>{if(!object.isMesh)return;object.material.opacity=group.userData.occlusionOpacity;object.material.depthWrite=group.userData.occlusionOpacity>.45})})}
